UPDATE show_review
SET content = #{content}, update_time = #{updateTime}
WHERE id = #{id}

mapper.select:
SELECT r.id, r.show_id, r.user_id, r.order_id, r.parent_id, r.reply_to_user_id, r.content, r.rating, r.like_count, r.reply_count, r.status, r.create_time, r.update_time, u.username AS username, NULL AS reply_to_username FROM show_review r LEFT JOIN `user` u ON u.id = r.user_id WHERE r.show_id = #{showId} AND r.parent_id IS NULL AND r.status <> 2
ORDER BY r.like_count DESC, r.create_time DESC ORDER BY r.create_time DESC
LIMIT #{size} OFFSET #{offset}

SELECT , NULL AS username, NULL AS reply_to_username
FROM show_review WHERE user_id = #{userId}
ORDER BY id DESC
LIMIT #{size} OFFSET #{offset}

SELECT r.id, r.show_id, r.user_id, r.order_id, r.parent_id, r.reply_to_user_id, r.content, r.rating, r.like_count, r.reply_count, r.status, r.create_time, r.update_time, u.username AS username, NULL AS reply_to_username FROM show_review r LEFT JOIN `user` u ON u.id = r.user_id
AND r.show_id = #{showId} AND r.status = #{status} AND r.content LIKE CONCAT('%', #{keyword}, '%')
ORDER BY r.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM show_review r

    AND r.show_id = #{showId}
    AND r.status = #{status}
    AND r.content LIKE CONCAT('%', #{keyword}, '%')
